(() => {
  // 自动定位主酒馆窗口（兼容 iframe 沙箱）
  let W = window;
  try { while (!W.document.getElementById('chat') && W !== W.parent) W = W.parent; } catch (e) {}
  const D = W.document;
  W.__ncm2?.();

  const LS = 'ncm2_v1';
  let st = {};
  try { st = JSON.parse(W.localStorage.getItem(LS)) || {}; } catch (e) {}
  const save = () => { try { W.localStorage.setItem(LS, JSON.stringify(st)); } catch (e) {} };

  D.getElementById('ncm2-style')?.remove();
  const css = D.createElement('style'); css.id = 'ncm2-style';
  css.textContent = `
    #ncm2-fab{position:fixed;z-index:99998;width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:21px;cursor:pointer;user-select:none;color:#fff;background:linear-gradient(135deg,#ff5b5e,#c9162b);box-shadow:0 6px 18px rgba(0,0,0,.35);touch-action:none;}
    #ncm2-fab:active{transform:scale(.92);}
    #ncm2{position:fixed;z-index:99999;width:320px;max-width:92vw;height:462px;display:none;flex-direction:column;border-radius:14px;overflow:hidden;background:#1f1f23;color:#ececec;border:1px solid rgba(127,127,127,.25);box-shadow:0 14px 44px rgba(0,0,0,.55);font-family:"LXGW WenKai","Kaiti SC","STKaiti",sans-serif;font-size:13px;}
    #ncm2.show{display:flex;animation:n2in .2s ease;}
    @keyframes n2in{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}
    #ncm2 .n2-head{display:flex;align-items:center;gap:6px;padding:9px 10px;background:rgba(0,0,0,.22);}
    #ncm2 .n2-head .t{flex:1;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    #ncm2 .n2-head button{background:rgba(127,127,127,.25);border:none;color:#eee;border-radius:7px;padding:4px 8px;font-size:12px;cursor:pointer;}
    #ncm2 .n2-body{flex:1;overflow:auto;padding:6px;}
    #ncm2 .n2-row{padding:8px 9px;border-radius:8px;cursor:pointer;display:flex;gap:8px;align-items:center;}
    #ncm2 .n2-row:active{background:rgba(255,255,255,.08);}
    #ncm2 .n2-row .nm{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    #ncm2 .n2-row .sub{opacity:.5;font-size:11px;max-width:40%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    #ncm2 .n2-row.on .nm{color:#ff6b6e;}
    #ncm2 .n2-center{padding:20px 16px;text-align:center;opacity:.92;line-height:1.8;}
    #ncm2 .n2-center img{width:184px;height:184px;border-radius:10px;background:#fff;padding:6px;box-sizing:border-box;}
    #ncm2 .n2-center input{width:100%;box-sizing:border-box;margin:8px 0;padding:8px 9px;border-radius:8px;border:1px solid rgba(127,127,127,.3);background:rgba(255,255,255,.07);color:#eee;font-size:12px;outline:none;}
    #ncm2 .n2-center .go{background:#c9162b;color:#fff;border:none;border-radius:8px;padding:7px 16px;cursor:pointer;font-size:13px;}
    #ncm2 .n2-foot{display:none;align-items:center;gap:8px;padding:8px 10px;background:rgba(0,0,0,.28);border-top:1px solid rgba(127,127,127,.18);}
    #ncm2 .n2-foot .pp{width:34px;height:34px;border-radius:50%;border:none;background:#c9162b;color:#fff;font-size:14px;cursor:pointer;flex:none;}
    #ncm2 .n2-foot .nav{background:none;border:none;color:#ccc;cursor:pointer;font-size:13px;flex:none;}
    #ncm2 .n2-foot .info{flex:1;min-width:0;}
    #ncm2 .n2-foot .info .nm{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px;}
    #ncm2 .n2-foot .info .pg{height:3px;background:rgba(255,255,255,.15);border-radius:2px;margin-top:5px;overflow:hidden;}
    #ncm2 .n2-foot .info .pg>i{display:block;height:100%;width:0;background:#ff5b5e;}
    .n2-toast{position:fixed;z-index:100000;left:50%;bottom:84px;transform:translateX(-50%);background:rgba(0,0,0,.82);color:#fff;padding:8px 14px;border-radius:8px;font-size:12px;opacity:0;transition:opacity .25s;pointer-events:none;max-width:80vw;text-align:center;}
    .n2-toast.show{opacity:1;}`;
  D.head.appendChild(css);
  if (!D.getElementById('anno-font')) { const lk = D.createElement('link'); lk.id = 'anno-font'; lk.rel = 'stylesheet'; lk.href = 'https://fastly.jsdelivr.net/npm/lxgw-wenkai-webfont/style.css'; D.head.appendChild(lk); }

  const fab = D.createElement('div'); fab.id = 'ncm2-fab'; fab.textContent = '♫'; D.body.appendChild(fab);
  const box = D.createElement('div'); box.id = 'ncm2'; D.body.appendChild(box);
  const toastEl = D.createElement('div'); toastEl.className = 'n2-toast'; D.body.appendChild(toastEl);
  let toastT = null;
  const toast = (m) => { toastEl.textContent = m; toastEl.classList.add('show'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('show'), 2400); };

  fab.style.left = (st.fx != null ? st.fx : (W.innerWidth - 60)) + 'px';
  fab.style.top = (st.fy != null ? st.fy : (W.innerHeight - 150)) + 'px';

  const api = async (path, params) => {
    params = params || {};
    if (!st.api) throw new Error('未设置 API 地址');
    const base = st.api.replace(/\/+$/, '');
    const u = new URL(base + '/' + String(path).replace(/^\//, ''));
    params.timestamp = Date.now();
    if (st.cookie) params.cookie = st.cookie;
    for (const k in params) if (params[k] != null) u.searchParams.set(k, params[k]);
    const r = await fetch(u.toString());
    return r.json();
  };

  const escp = s => (s || '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  const arts = s => ((s.ar || s.artists || []).map(a => a.name).join('/'));

  // 播放
  const audio = new W.Audio();
  let queue = [], qi = -1;
  audio.addEventListener('timeupdate', () => { const f = box.querySelector('.pg>i'); if (f && audio.duration) f.style.width = (audio.currentTime / audio.duration * 100) + '%'; });
  audio.addEventListener('ended', () => next());
  const setPP = () => { const b = box.querySelector('.pp'); if (b) b.textContent = audio.paused ? '▶' : '⏸'; };
  audio.addEventListener('play', setPP); audio.addEventListener('pause', setPP);

  const markRow = () => { box.querySelectorAll('.n2-row').forEach(r => r.classList.toggle('on', +r.dataset.i === qi)); };
  const renderFoot = (s) => { const f = box.querySelector('.n2-foot'); if (!f) return; f.style.display = 'flex'; f.querySelector('.nm').textContent = s.name + ' - ' + arts(s); setPP(); };
  const playAt = async (i) => {
    if (i < 0 || i >= queue.length) return;
    qi = i; const s = queue[i]; markRow();
    let url = null;
    try { const u = await api('/song/url/v1', { id: s.id, level: 'exhigh' }); url = u && u.data && u.data[0] && u.data[0].url; } catch (e) {}
    if (!url) { try { const u2 = await api('/song/url', { id: s.id }); url = u2 && u2.data && u2.data[0] && u2.data[0].url; } catch (e) {} }
    if (!url) { toast('无法播放(版权/VIP)：' + s.name); return; }
    audio.src = url; audio.play().catch(() => {}); renderFoot(s);
  };
  const next = () => playAt(qi + 1 >= queue.length ? 0 : qi + 1);
  const prev = () => playAt(qi - 1 < 0 ? queue.length - 1 : qi - 1);

  let view = 'login', qrTimer = null;
  const body = () => box.querySelector('.n2-body');
  const setHead = (title, back, logout) => {
    box.querySelector('.t').textContent = title;
    box.querySelector('.back').style.display = back ? '' : 'none';
    box.querySelector('.lo').style.display = logout ? '' : 'none';
  };
  const shell = () => {
    box.innerHTML = `
      <div class='n2-head'>
        <button class='back' style='display:none'>‹ 返回</button>
        <span class='t'>网易云</span>
        <button class='set'>⚙</button>
        <button class='lo' style='display:none'>退出</button>
      </div>
      <div class='n2-body'></div>
      <div class='n2-foot'>
        <button class='nav pv'>⏮</button>
        <button class='pp'>▶</button>
        <button class='nav nx'>⏭</button>
        <div class='info'><div class='nm'>未播放</div><div class='pg'><i></i></div></div>
      </div>`;
    box.querySelector('.back').onclick = () => showPlaylists();
    box.querySelector('.set').onclick = () => showSettings();
    box.querySelector('.lo').onclick = () => { st.cookie = ''; st.uid = null; save(); showLogin(); };
    box.querySelector('.pp').onclick = () => { audio.paused ? audio.play() : audio.pause(); };
    box.querySelector('.pv').onclick = prev;
    box.querySelector('.nx').onclick = next;
    if (queue.length && qi >= 0) renderFoot(queue[qi]);
  };

  const showSettings = () => {
    view = 'settings'; setHead('设置', false, !!st.cookie);
    body().innerHTML = `<div class='n2-center'>
      <div style='text-align:left;opacity:.85;font-size:12px'>后端 API 地址（你的 NeteaseCloudMusicApi）</div>
      <input class='apiv' placeholder='https://你的域名' value='${escp(st.api || '')}'>
      <button class='go'>保存</button>
      <div style='margin-top:10px;font-size:11px;opacity:.55;text-align:left'>必须是 https，否则手机端会被混合内容拦截。保存后回到扫码登录。</div>
    </div>`;
    body().querySelector('.go').onclick = () => { st.api = body().querySelector('.apiv').value.trim(); save(); st.cookie ? afterLogin() : showLogin(); };
  };

  const showLogin = async () => {
    clearInterval(qrTimer); view = 'login'; setHead('扫码登录', false, false);
    if (!st.api) { showSettings(); toast('请先填后端 API 地址'); return; }
    body().innerHTML = `<div class='n2-center'>正在获取二维码…</div>`;
    try {
      const k = await api('/login/qr/key');
      const key = k && k.data && k.data.unikey;
      if (!key) { body().innerHTML = `<div class='n2-center'>取码失败，请检查 API 地址<br><br><button class='go'>去设置</button></div>`; body().querySelector('.go').onclick = showSettings; return; }
      const c = await api('/login/qr/create', { key, qrimg: true });
      const img = c && c.data && c.data.qrimg;
      body().innerHTML = `<div class='n2-center'><img src='${img}'><div class='qs' style='margin-top:8px'>用网易云音乐 App 扫码</div><div style='margin-top:10px'><button class='go'>刷新二维码</button></div></div>`;
      body().querySelector('.go').onclick = () => showLogin();
      qrTimer = setInterval(async () => {
        let s; try { s = await api('/login/qr/check', { key }); } catch (e) { return; }
        const qs = body().querySelector('.qs');
        if (s.code === 802 && qs) qs.textContent = '已扫描，请在手机点确认';
        else if (s.code === 801 && qs) qs.textContent = '用网易云音乐 App 扫码';
        else if (s.code === 800) { clearInterval(qrTimer); if (qs) qs.textContent = '二维码已过期，点刷新'; }
        else if (s.code === 803) { clearInterval(qrTimer); st.cookie = s.cookie; save(); toast('登录成功'); afterLogin(); }
      }, 2500);
    } catch (e) {
      body().innerHTML = `<div class='n2-center'>连接后端失败<br><span style='font-size:11px;opacity:.6'>${escp((e && e.message) || '')}</span><br><br><button class='go'>去设置</button></div>`;
      body().querySelector('.go').onclick = showSettings;
    }
  };

  const afterLogin = async () => {
    try {
      const acc = await api('/user/account');
      st.uid = (acc && acc.account && acc.account.id) || (acc && acc.profile && acc.profile.userId);
      save();
      if (!st.uid) { showLogin(); return; }
      showPlaylists();
    } catch (e) { toast('读取账号失败'); showSettings(); }
  };

  const showPlaylists = async () => {
    view = 'playlists'; setHead('我的歌单', false, true);
    body().innerHTML = `<div class='n2-center'>加载歌单…</div>`;
    try {
      const p = await api('/user/playlist', { uid: st.uid, limit: 80 });
      const ls = (p && p.playlist) || [];
      body().innerHTML = ls.map(pl => `<div class='n2-row' data-pid='${pl.id}'><span class='nm'>${escp(pl.name)}</span><span class='sub'>${pl.trackCount || 0}首</span></div>`).join('') || `<div class='n2-center'>没有歌单</div>`;
      body().querySelectorAll('.n2-row').forEach(r => r.onclick = () => openPlaylist(r.dataset.pid, r.querySelector('.nm').textContent));
    } catch (e) { body().innerHTML = `<div class='n2-center'>加载失败</div>`; }
  };

  const openPlaylist = async (pid, name) => {
    view = 'tracks'; setHead(name || '歌单', true, false);
    body().innerHTML = `<div class='n2-center'>加载歌曲…</div>`;
    try {
      const t = await api('/playlist/track/all', { id: pid, limit: 500 });
      const songs = (t && t.songs) || [];
      queue = songs; qi = -1;
      body().innerHTML = songs.map((s, i) => `<div class='n2-row' data-i='${i}'><span class='nm'>${escp(s.name)}</span><span class='sub'>${escp(arts(s))}</span></div>`).join('') || `<div class='n2-center'>空歌单</div>`;
      body().querySelectorAll('.n2-row').forEach(r => r.onclick = () => playAt(+r.dataset.i));
    } catch (e) { body().innerHTML = `<div class='n2-center'>加载失败</div>`; }
  };

  const renderView = () => {
    if (!st.api) showSettings();
    else if (!st.cookie) showLogin();
    else if (view === 'tracks' && queue.length) { /* 保持当前曲目列表 */ }
    else if (view === 'settings') showSettings();
    else showPlaylists();
  };

  // 拖动 + 开关
  const place = () => { const r = fab.getBoundingClientRect(); let left = Math.max(8, Math.min(r.left, W.innerWidth - 320 - 8)); let top = r.top - 472; if (top < 8) top = Math.min(r.bottom + 8, W.innerHeight - 470); box.style.left = left + 'px'; box.style.top = Math.max(8, top) + 'px'; };
  const toggle = (show) => {
    const ws = show == null ? !box.classList.contains('show') : show;
    if (ws) { place(); box.classList.add('show'); renderView(); }
    else { box.classList.remove('show'); clearInterval(qrTimer); }
  };
  let drag = null;
  const down = (e) => { const p = e.touches ? e.touches[0] : e; drag = { x: p.clientX, y: p.clientY, l: fab.offsetLeft, t: fab.offsetTop, moved: false }; };
  const move = (e) => {
    if (!drag) return; const p = e.touches ? e.touches[0] : e;
    const dx = p.clientX - drag.x, dy = p.clientY - drag.y;
    if (Math.abs(dx) + Math.abs(dy) > 4) drag.moved = true;
    fab.style.left = Math.max(4, Math.min(drag.l + dx, W.innerWidth - 48)) + 'px';
    fab.style.top = Math.max(4, Math.min(drag.t + dy, W.innerHeight - 48)) + 'px';
    if (box.classList.contains('show')) place();
    if (drag.moved) e.preventDefault();
  };
  const up = () => { if (!drag) return; if (!drag.moved) toggle(); else { st.fx = fab.offsetLeft; st.fy = fab.offsetTop; save(); } drag = null; };
  fab.addEventListener('mousedown', down); D.addEventListener('mousemove', move); D.addEventListener('mouseup', up);
  fab.addEventListener('touchstart', down, { passive: false }); D.addEventListener('touchmove', move, { passive: false }); D.addEventListener('touchend', up);
  W.addEventListener('resize', () => { if (box.classList.contains('show')) place(); });

  shell();

  W.__ncm2 = () => { clearInterval(qrTimer); audio.pause(); audio.src = ''; fab.remove(); box.remove(); toastEl.remove(); css.remove(); D.removeEventListener('mousemove', move); D.removeEventListener('mouseup', up); D.removeEventListener('touchmove', move); D.removeEventListener('touchend', up); };
})();
